from PIL import Image
import numpy as np

img = Image.open('/home/ctfplayer/xor_diff.png')
data = np.array(img)

ascii_chars = []
rows, cols = data.shape[:2]
channels = 1 if len(data.shape) == 2 else data.shape[2]
for i in range(rows):
    for j in range(cols):
        px = data[i, j]
        if channels == 1:
            vals = [px]
        else:
            vals = px
        for val in vals:
            if 32 <= val <= 126:
                ascii_chars.append(chr(val))
            else:
                ascii_chars.append('.')

ascii_text = ''.join(ascii_chars)
with open('/home/ctfplayer/xor_diff_ascii.txt','w') as f:
    f.write(ascii_text)

from PIL import Image, ImageEnhance, ImageOps
import pytesseract
import os

def enhance_and_ocr(path, enhancements):
    image = Image.open(path)
    for enhance_type, factor in enhancements:
        if enhance_type == 'contrast':
            image = ImageEnhance.Contrast(image).enhance(factor)
        elif enhance_type == 'brightness':
            image = ImageEnhance.Brightness(image).enhance(factor)
        elif enhance_type == 'sharpness':
            image = ImageEnhance.Sharpness(image).enhance(factor)
        elif enhance_type == 'invert':
            image = ImageOps.invert(image.convert('RGB'))
    return pytesseract.image_to_string(image, lang='eng')

variants = [
    [],
    [('contrast', 3.0)],
    [('sharpness', 2.0)],
    [('contrast', 3.0), ('sharpness', 2.0)],
    [('contrast', 3.0), ('invert', 0)],
    [('brightness', 1.5), ('contrast', 3.0)],
]

outputs = []
for idx, enh in enumerate(variants):
    txt = enhance_and_ocr('/home/ctfplayer/ctf_files/xor_diff.png', enh)
    outputs.append(f'---Variant {idx}---\n{txt}')

with open('/home/ctfplayer/ctf_files/ocr_outputs.txt', 'w') as f:
    for o in outputs:
        f.write(o + '\n')
